const photos={car:'assets/hero-car.avif',sedan:'assets/sedan.avif',suv:'assets/premium.avif'};
const cars=[{id:'camaro',name:'Chevrolet Camaro',category:'sport',label:'Спорт',price:9000,gear:'Автомат',seats:4,image:photos.sedan},{id:'panamera',name:'Porsche Panamera',category:'business',label:'Бизнес',price:11000,gear:'Автомат',seats:4,image:photos.car},{id:'amg-gt',name:'Mercedes-AMG GT',category:'premium',label:'Премиум',price:16000,gear:'Автомат',seats:2,image:photos.suv}];
const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('ru-RU').format(n),config=window.RENTAL_CONFIG||{};let filter='all',copyText='',handoffGeneration=0;
function handlePhotos(){document.querySelectorAll('[data-photo]').forEach(img=>{if(img.dataset.bound)return;img.dataset.bound='1';const failed=()=>{img.classList.add('no-photo');img.setAttribute('aria-hidden','true');};const loaded=()=>{const fallback=img.parentElement.querySelector('.image-fallback');if(fallback)fallback.hidden=true;};img.addEventListener('load',loaded);img.addEventListener('error',failed);if(img.complete){if(img.naturalWidth)loaded();else failed();}});}
function period(){const start=$('#start').value,end=$('#end').value;const a=new Date(start+'+03:00'),b=new Date(end+'+03:00');if(!start||!end||!Number.isFinite(+a)||!Number.isFinite(+b))throw Error('Укажите даты и время получения и возврата.');if(a<=new Date())throw Error('Выберите время получения в будущем.');if(b<=a)throw Error('Возврат должен быть позже получения.');if(b-a>90*86400000)throw Error('Для аренды более 90 дней свяжитесь с менеджером.');return{start:a.toISOString(),end:b.toISOString(),days:Math.ceil((b-a)/86400000)};}
function render(){$('#cars').innerHTML=cars.filter(c=>filter==='all'||c.category===filter).map((c,i)=>`<article class="car"><div class="car-image"><div class="image-fallback"><span>ФАЭТОН / КМВ</span><strong>${c.name}</strong><small>Фотография временно недоступна</small></div><img data-photo src="${c.image}" alt="Иллюстративная фотография автомобиля, не фактическая машина ${c.name}" loading="lazy"><span class="class-tag">${c.label}</span></div><div class="car-body"><div class="car-title"><h3>${c.name}</h3><span>0${cars.indexOf(c)+1}</span></div><div class="specs"><span>${c.gear}</span><span>${c.seats} мест</span><span>Кондиционер</span></div><div class="car-bottom"><div class="price">${money(c.price)} ₽ <small>/ сутки</small></div><button data-car="${c.id}" aria-label="Рассчитать аренду ${c.name}">↗</button></div></div></article>`).join('');document.querySelectorAll('[data-car]').forEach(b=>b.onclick=()=>choose(b.dataset.car));handlePhotos();}
function validate(){try{const p=period();$('#date-error').textContent='';return p;}catch(e){$('#date-error').textContent=e.message;return null;}}
function choose(id){const p=validate();if(!p){$('#booking').scrollIntoView({behavior:'smooth'});$('#start').focus({preventScroll:true});return;}const c=cars.find(c=>c.id===id),fmt=s=>new Date(s).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',dateStyle:'short',timeStyle:'short'});const token=++handoffGeneration;$('#selected-name').textContent=c.name;copyText=`Минеральные Воды · время МСК\nПолучение: ${fmt(p.start)}\nВозврат: ${fmt(p.end)}\nПериод: ${p.days} сут. × ${money(c.price)} ₽\nПредварительно: ${money(p.days*c.price)} ₽`;$('#summary').textContent=copyText;$('#copy-status').textContent='';$('#bot-link').hidden=true;$('#bot-status').textContent='Бот еще не подключен. Скопируйте расчет для обсуждения с менеджером. Эта версия не создает бронирование.';$('#booking-dialog').showModal();if(config.apiBase&&config.botUsername)handoff(c,p,token);}
async function handoff(c,p,generation){try{const res=await fetch(config.apiBase.replace(/\/$/,'')+'/api/bookings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({car_id:c.id,start:p.start,end:p.end}),signal:AbortSignal.timeout(12000)});if(!res.ok)throw Error();const data=await res.json();if(generation!==handoffGeneration||!$('#booking-dialog').open)return;if(!/^[A-Za-z0-9_-]{10,64}$/.test(data.token)||!/^\w{5,32}$/.test(config.botUsername))throw Error();$('#bot-link').href=`https://t.me/${config.botUsername}?start=${data.token}`;$('#bot-link').hidden=false;$('#bot-status').textContent='Продолжите оформление в Telegram. Наличие и окончательные условия подтвердит менеджер.';}catch{if(generation===handoffGeneration)$('#bot-status').textContent='Сервер временно недоступен. Попробуйте позже. Бронирование не подтверждено.';}}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});render();});$('#find').onclick=()=>{if(validate())$('#fleet').scrollIntoView({behavior:'smooth'});};$('.close').onclick=()=>$('#booking-dialog').close();$('#booking-dialog').addEventListener('close',()=>{handoffGeneration++;});$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#selected-name').textContent+'\n'+copyText+'\nУсловия требуют подтверждения менеджера.');$('#copy-status').textContent='Расчет скопирован.';}catch{$('#copy-status').textContent='Выделите расчет и скопируйте вручную.';}};
const now=Date.now(),local=d=>new Date(d+10800000).toISOString().slice(0,16);$('#start').min=local(now);$('#start').value=local(Math.ceil((now+86400000)/3600000)*3600000);$('#end').value=local(Math.ceil((now+4*86400000)/3600000)*3600000);render();handlePhotos();
if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(x=>{if(x.isIntersecting){x.target.classList.add('is-visible');observer.unobserve(x.target);}}),{threshold:.05});document.querySelectorAll('.section-heading,.tips article,.how li').forEach(x=>{x.classList.add('show-on-scroll');observer.observe(x);});document.body.classList.add('reveal-on');}



